def is_town(st):
    return isinstance(st, _WTS)


def is_dun(st):
    return isinstance(st, DungeonState)


def is_map(st):
    return is_town(st) or is_dun(st)


def pos(st):
    return tuple(st.player) if is_town(st) else tuple(st.run.player)


def loc():
    """Where you are: (area, room or floor)."""
    st = g.current_state
    if is_town(st):
        return (st.area_key, "room:" + st.room if st.room else "outside")
    if is_dun(st):
        return (st.area_key, "floor:%d" % st.run.index)
    return (story.current_area_key, type(st).__name__)


def here():
    st = g.current_state
