def settle(limit=9000):
    """Run the game, tapping through what's said and winning what's fought, till it waits for you on a map."""
    calm = odd = 0
    for i in range(limit):
        st = g.current_state
        STATE["frames"] += 1
        try:
            if isinstance(st, _UVS):   # (Black 2 or White 2, whenever the pick comes up, before anything else reads the screen: Black 2)
                if not STATE.get("version_said"):
                    STATE["version_said"] = True
                    _say("[version: Black 2]")
                st.choose("BLACK_2")
                for _k in range(400):
                    if g.current_state is not st:
                        break
                    if getattr(st, "dialogue_box", None) is not None and getattr(st.dialogue_box, "visible", False):
                        st.dialogue_box.advance()
                    st.update(); st.draw()
                continue
            if isinstance(st, TrainerIntroState) and isinstance(getattr(st, "next_state", None), TrainerBattleState):
                b = st.next_state
                g.change_state(b)
                _win(b)
                continue
            if isinstance(st, TrainerBattleState):
                _win(st)
                continue
            if type(st).__name__ in ("HallOfFameState", "IntroSpeechState"):   # (11-19: the Hall of Fame / the opening talk - tap on, as a player does)
                if not STATE.get("hof_seen") and type(st).__name__ == "HallOfFameState":
                    STATE["hof_seen"] = True
                    _say("[Hall of Fame: the team shown, Mom's call]")
                st.handle_events([pygame.event.Event(pygame.MOUSEBUTTONDOWN, button=1, pos=(640, 600))])
                st.update(); st.draw()
                continue
            if isinstance(st, _SPS):
                STATE["puzzles"] += 1
                _say("[slide puzzle solved]")
                st._finish(True)
                continue
            if isinstance(st, _MG):   # (a Gym's game before its Leader: counted as won, as the battles are)
                STATE["puzzles"] += 1
                _say(f"[minigame won: {type(st).__name__}]")
                st.on_done(True)
                continue
            if isinstance(st, _GPS) and not st.finished:
                STATE["puzzles"] += 1
                _say(f"[puzzle solved: {st.kind}]")
                st._finish(True)
            if isinstance(st, _GLS):   # (the old Gym lobby screen: CHALLENGE, or EXIT GYM once it's cleared)
                STATE["seen_states"]["GymLobbyState"] += 1
                if st.is_cleared or STATE["seen_states"]["GymLobbyState"] > 40 or not st.next_opponent and not getattr(st, "challenge", None):
                    _say("[Gym lobby screen: EXIT GYM]")
                    st.exit_gym()
                else:
                    _say("[Gym lobby screen: CHALLENGE]")
                    st.challenge_gym()
                    if g.current_state is st:
                        st.exit_gym()
                continue
            _lp = getattr(getattr(st, "back", None), "_lift_plan", None)
            if isinstance(st, _PLS) and st.title == "WHICH FLOOR?" and _lp in [v for _l, v in st.choices]:   # (a lift's panel: the floor the marker
                _say(f"[lift: {st.title}: {next(l for l, v in st.choices if v == _lp)}]")                    #  says, 'Lift to <floor>'; 11-23)
                st.back._lift_plan = None
                st.pick(_lp)
                continue
            if isinstance(st, _PLS):   # (a list to pick from: a tutor's "who should learn it?": BACK, no thanks)
                if str(st.title).endswith("?") and str(st.title) != str(st.title).upper() and st.choices:   # (Johto: the Elder's quiz)
                    _say(f"[list: {st.title}: answered {st.choices[0][0]}]")
                    st.pick(st.choices[0][1])
                    continue
                _say(f"[list: {st.title}: BACK]")
                st.pick(None)
                continue
            if type(st).__name__ == "MovieState":   # (Pokestar Studios' movie game: the first script, the good line every beat)
                _st0 = (st.stage, getattr(st, "beat", 0))
                if st.stage == "pick":
                    st.stage_t = -10 ** 6
                    st.handle_events([pygame.event.Event(pygame.KEYDOWN, key=pygame.K_1, mod=0, unicode="1")])   # (the first script)
                elif st.stage == "beat":
                    _o = st._order()
                    st._choose(next((j for j, (_t, kind) in enumerate(_o) if kind == "good"), 0))
                else:
                    st.stage_t = -10 ** 6
                    st._next()
                st.update(); st.draw()
                if g.current_state is st and (st.stage, getattr(st, "beat", 0)) == _st0:   # (nothing moved: let the frames run)
                    settle(5)
                continue
            if type(st).__name__ == "TextPromptState":   # (words to type: Join Avenue's greeting, B2W2's Easy Chat: a short word)
                _say(f"[typed: Hello! for {st.title}]")
                st.text = "Hello!" if hasattr(st, "text") else None
                st.confirm()
                continue
            if isinstance(st, _SSS):
                st.load_starters()
                st.selected_idx = [p.id for p in st.starters].index(498) if 498 in [p.id for p in st.starters] else 0   # (Tepig)
                st.complete_selection()
                _say(f"[starter chosen: {st.starters[st.selected_idx].name}]")
                if st.dialogue_box.callback:
                    st.dialogue_box.callback()
                continue
            if is_town(st):
                STATE["last_map"] = st
                if st.toast_timer > 0 and st.toast:
                    _say("(" + st.toast + ")")
                if st.npc_active and getattr(st, "choice_active", False):   # (a yes / no question: yes)
                    _note(st)
                    _say("[yes]")
                    st.yes_btn.callback()
                    calm = 0
                elif st.npc_active:
                    _note(st); _click(st); calm = 0
                elif st.hover_menu_active:
                    _pick_hover(st); calm = 0
                elif st.anim > 0 or getattr(st, "_scene_lock", False):
                    calm = 0
                else:
                    calm += 1
            elif is_dun(st):
                STATE["last_map"] = st
                if hasattr(st, "run"):
                    f = st.run.floor
                    if any(m.kind == "wild" for m in f.movers) and st.mode == "MAP":
                        f.movers = [m for m in f.movers if m.kind != "wild"]   # (no wild Pokemon: the story only)
                if getattr(st, "toast_timer", 0) > 0 and st.toast:
                    _say("(" + st.toast + ")")
                if st.mode == "CHOICE":   # (a wild Pokemon after all: leave it)
                    m = st.encounter
                    st.encounter = None
                    st.mode = "MAP"
                    if m is not None:
                        st.run.remove(m)
                    calm = 0
                elif st.dialogue_box.visible:
                    _note(st)
                    yes = getattr(st, "btn_yes", None)
                    if yes is not None and getattr(yes, "visible", False) and yes.callback and st.mode != "CATCH":
                        _say("[yes]")
                        yes.callback()
                    else:
                        st.dialogue_box.advance()
                    calm = 0
                elif st.mode != "MAP" or getattr(st, "_walker", None) or st.anim > 0 or st.sliding or getattr(st, "_scene_lock", False):
                    calm = 0
                    odd += 1 if st.mode not in ("MAP", "SPOTTED", "APPROACH") else 0
                    if odd > 600:
                        _back_out(st, f"the map stayed in mode {st.mode}")
                        st.mode = "MAP"
                        odd = 0
                else:
                    calm += 1
            else:
                name = type(st).__name__
                STATE["seen_states"][name] += 1
                if name == "RivalSelectionState" and STATE.get("mission") == "tour":
                    return st
                box = getattr(st, "dialogue_box", None)
                if box is not None and getattr(box, "visible", False):
                    _note(st)
                    box.advance()
                odd += 1
                if odd > (2500 if isinstance(st, AreaTransitionState) else 500):
                    _back_out(st, "nothing the script does moves it on")
                    odd = 0
                    continue
            st = g.current_state
            st.update()
            if i % 6 == 0:
                st.draw()
        except Exception:
            crash(f"running {type(st).__name__}")
            if not is_map(g.current_state) or STATE["crashes"] > 60:
                _back_out(g.current_state, "it crashed")
            calm = 0
            odd += 50
            if odd > 600:
                return g.current_state
        if calm >= 2:
            return g.current_state
    st = g.current_state
    what = f"the game never came back to the player ({type(st).__name__}" + (f", talking: {said[-1][:80]!r}" if getattr(st, "npc_active", False) and said else "")         + (", a scene still running" if getattr(st, "_scene_lock", False) else "") + f"; {limit} frames)"
    if not any(f["kind"] == "HANG" and f["where"] == here() for f in FIND):
        FIND.append({"kind": "HANG", "mission": STATE["mission"], "where": here(), "what": what, "shot": shot("hang"), "said": said[-6:]})
        print(f"FAIL HANG at {here()}: {what}", flush=True)
    if getattr(g, "transitioning", False):   # (game.transitioning, set by a Gym or League battle's start and cleared only by the
        g.transitioning = False               #  lobby screen / a minigame / a puzzle starting: the next Leader's "Let's battle" does nothing)
        for f in FIND:
            if f["kind"] == "HANG" and f["where"] == here():
                f["latch"] = True
                f["what"] += " | game.transitioning was still True from the battle before (the script cleared it to go on)"
        print(f"  .... game.transitioning was still True at {here()}: cleared by the script (a skip)", flush=True)
        STATE["latch"] = True
        MEM["retry_here"] = True
    try:   # (so the run can go on: close what was open)
        if is_town(st):
            st._scene_lock = False
            if st.npc_active:
                st.choice_active = False
                st.end_npc_interaction()
        elif is_dun(st):
            st._scene_lock = False
            st.dialogue_box.visible = False
            st.mode = "MAP"
            st._walker = None
    except Exception:
        crash("closing a screen that hung")
    return st


# ---------------------------------------------------------------- where a step takes you (the game's own tests)
def t_step(st, p, d, through=False):
    """A town map: the tile a step from p ends on, and whether it leaves the map there (a way out, a pad into a room)."""
    to = (p[0] + d[0], p[1] + d[1])
    if not (0 <= to[0] < st.w and 0 <= to[1] < st.h):
        return None
    grid = getattr(st, "grid", None)
    if grid and _art.LEDGES.get(grid[to[1]][to[0]]) == d:
        over = (to[0] + d[0], to[1] + d[1])
        if st._open(over) and over not in st.doors and over not in st.signs:
            to = over
    if grid and grid[to[1]][to[0]] in "207":
        return None
    if not st._open(to):
        return None
    pits = getattr(st, "pits", None)
    if pits and grid and grid[to[1]][to[0]] in pits.get("chars", "m"):
        return None
    if to in st.exits:
        return to, True
    links = getattr(st, "links", None) or {}
    if to in links:
        if to in (getattr(st, "room_links", None) or {}):
            return to, True
        return tuple(links[to]), False
    if grid and grid[to[1]][to[0]] in "3456":
        way = {"3": (-1, 0), "4": (1, 0), "5": (0, -1), "6": (0, 1)}
        dd, cur = way[grid[to[1]][to[0]]], to
        for _ in range(st.w * st.h):
            nxt = (cur[0] + dd[0], cur[1] + dd[1])
            if not st._open(nxt) or nxt in st.doors or nxt in st.signs:
                break
            cur = nxt
            if grid[cur[1]][cur[0]] in way:
                dd = way[grid[cur[1]][cur[0]]]
            elif cur in st.stops or cur in st.exits or cur in links:
                break
        return cur, cur in st.exits
    return to, False


def d_step(st, p, d, through=False):
    """A route or cave floor: the same. through: a trainer or a boulder (with Strength) counts as a way through (you
    walk into it: the battle, the push)."""
    f = st.run.floor
    to = (p[0] + d[0], p[1] + d[1])
    dec = str(f.decor.get(to, ""))
    if dec == "ledge:%d,%d" % d:
        over = (to[0] + d[0], to[1] + d[1])
        if not (f.walkable(*over) and f.mover_at(*over) is None):
            return None
        to = over
    elif not f.walkable(*to):
        if through and dec.startswith(("boulder:", "crate:")) and (dec.startswith("crate:") or story.inventory.get("HM_STRENGTH", 0) > 0):
            return to, False
        if through and dec.startswith("whirl:") and story.inventory.get("HM_WHIRLPOOL", 0) > 0:   # (Johto: calmed by walking into it)
            return to, False
        if through and dec.startswith("crack:") and __import__("src.world.hms", fromlist=["field"]).field(story, "HM_ROCK_SMASH"):
            return to, False   # (a cracked rock on a map whose rocks hide Pokemon - "smash_wild": broken by walking into it)
        return None
    m = f.mover_at(*to)
    if m is not None and not (through and m.kind == "trainer"):
        return None
    if f.tile(*to) == core.SURF and f.tile(*p) != core.SURF and not st._can_surf():
        return None
    if to in f.exits:
        return to, True
    cur, dd, stops = to, d, st._stop_tiles()
    for _ in range(400):
        way = f.current.get(cur) or (dd if cur in f.ice else None)
        if not way or cur in stops:
            break
        nxt = (cur[0] + way[0], cur[1] + way[1])
        if not f.walkable(*nxt) or f.mover_at(*nxt) is not None:
            break
        cur, dd = nxt, way
        if cur in f.exits:
            return cur, True
    return cur, False


def _tile(n):
    return n[0] if isinstance(n[0], tuple) else n


def flood(st, through=False, blocked=()):
    """{tile: (the tile before, the step)} for every tile you can get to on this map as it stands now. (Johto: a tile of
    a log bridge is kept as (tile, the way you're crossing it), deck or under; see _bridge_bars.)"""
    fn = t_step if is_town(st) else d_step
    br = (getattr(st, "bridge", None) or {}) if is_town(st) else (getattr(st.run.floor, "bridge", None) or {})
    start = pos(st)
    if start in br:
        ax = br[start] if (getattr(st, "deck", True) if is_town(st) else getattr(st.run, "deck", True)) else (br[start][1], br[start][0])
        start = (start, ax)
    prev, q = {start: None}, deque([start])
    while q:
        pn = q.popleft()
        p = _tile(pn)
        mode = pn[1] if p in br and pn is not p else None
        for d in DIRS:
            if (p, d) in blocked:
                continue
            ad = (abs(d[0]), abs(d[1]))
            r = fn(st, p, d, through)
            if r is None:
                continue
            t, end = r
            if p in br and t not in br and mode is not None and ad != mode:   # (off a bridge only the way you're crossing it)
                continue
            tn = (t, (mode if p in br and mode is not None else ad)) if t in br else t
            if tn not in prev:
                prev[tn] = (pn, d)
                if not end:
                    q.append(tn)
    return prev


# ---------------------------------------------------------------- parts of a place, learned as the run walks (11-23)
# A place can be split into parts that join only through other places (Orange: Route 56's south half reaches its north
# half, and Route 67, only across Fairchild Island; Route 72's north bay opens only on Pummelo). The planner below works
# area by area, so it can't tell those halves apart. A part = the tiles you can reach from where you stand (flood), named
# by its first tile; every move that takes you from one part to another is written down (PART_EDGE), so later the run
# can go round the way it already knows (part_way): used only where the area-by-area planner has no way on.
PART_EDGE = collections.defaultdict(dict)   # part -> {tile you went to: the part it took you to}
PART_TRIED = collections.Counter()           # (part, tile): times part_way sent the run that way (2 at most: a trainer or a
                                             #  story bar can split a part differently from the time it was walked)


def part_of(st):
    """(area, room / floor, first tile) of the part of this map you stand in, or None off a map."""
    if not is_map(st):
        return None
    try:
        reach = flood(st)
    except Exception:
        return None
    L = loc()
    tiles = [t for t in reach if isinstance(t, tuple) and len(t) == 2 and all(isinstance(v, int) for v in t)]
    return (L[0], L[1], min(tiles)) if tiles else None


def part_way(st, area):
    """The tile to head for, here, on a way the run has walked before from this part to `area` (None if none known)."""
    p0 = part_of(st)
    if p0 is None:
        return None
    prev, q = {p0: None}, deque([p0])
    while q:
        p = q.popleft()
        if p[0] == area and p != p0:
            while prev[p] is not None and prev[p][0] != p0:
                p = prev[p][0]
            if prev[p] is None:
                return None
            PART_TRIED[(p0, prev[p][1])] += 1
            return prev[p][1]
        for tile, nxt in PART_EDGE.get(p, {}).items():
            if nxt not in prev and (p != p0 or PART_TRIED[(p0, tile)] < 2):
                prev[nxt] = (p, tile)
                q.append(nxt)
    return None


def _counter(st, t):
    if is_town(st):
        return bool(getattr(st, "room", None)) and 0 <= t[1] < st.h and 0 <= t[0] < st.w and st.grid[t[1]][t[0]] == "m"
    return st.run._art_char(*t) == "m"


def stands(st, goal):
    """Where to stand to walk into goal (someone, a door, a sign): beside it, or across a counter from it."""
    out_ = []
    for d in DIRS:
        one = (goal[0] - d[0], goal[1] - d[1])
        out_.append((one, d))
        if _counter(st, one):
            two = (one[0] - d[0], one[1] - d[1])
            out_.append((two, d))
            if _counter(st, two):
                out_.append(((two[0] - d[0], two[1] - d[1]), d))
    return out_


def _len(prev, t):
    n = 0
    while prev[t] is not None:
        t = prev[t][0]
        n += 1
    return n


def route(st, goal, through=False, blocked=(), prev=None):
    """The steps to goal: [(step, the tile it should end on)], the last one (step, None) when goal is walked INTO.
    None: no way there now. []: you're standing on it."""
    prev = prev if prev is not None else flood(st, through, blocked)
    goal = tuple(goal)
    bump = None
    pad = is_town(st) and goal in (getattr(st, "links", None) or {}) and goal != pos(st)   # (a warp pad: it's stepped onto, wherever that takes you; 11-17: standing on it by coming back through its far pad isn't taking it)
    if goal in prev and not pad:
        end = goal
    else:
        c = [(s, d) for s, d in stands(st, goal) if s in prev and (s, d) not in blocked]
        if not c:
            return None
        end, bump = min(c, key=lambda sd: _len(prev, sd[0]))
    steps, t = [], end
    while prev[t] is not None:
        p, d = prev[t]
        steps.append((d, _tile(t)))
        t = p
    steps.reverse()
    if bump:
        steps.append((bump, None))
    return steps


def _gust_safe(st, gc, t):
    from src.world import gusts as _gu
    return not _gu.in_lane(gc, t) or _gu.sheltered(st, gc, t)


def _gust_wait(st, path, k):
    """Before step k of path in a windy room: wait while it blows you along, then on a safe tile till the calm left is
    enough to reach the next safe tile on the path (Mistralton Gym's turbines, src/world/gusts.py)."""
    from src.world import gusts as _gu
    gc = _gu._cfg(st)
    if not gc:
        return
    every, warn, blow = int(gc.get("every", 300)), int(gc.get("warn", 90)), int(gc.get("blow", 40))
    cells = [w for _d, w in path[k:] if w is not None]
    need = next((i + 1 for i, w in enumerate(cells) if _gust_safe(st, gc, w)), len(cells))
    for _ in range(every * 3):
        if g.current_state is not st:
            return
        sliding = getattr(st, "_gust_slide", False) or st.anim > 0
        left = every - blow - warn - getattr(st, "_gust_t", 0) % max(1, every)
        if not sliding and (not _gu.in_lane(gc, cells[0] if cells else pos(st)) or
                            (_gu.phase(st) == "calm" and left > (need + 2) * (STEP_GUST_FRAMES + 2))):
            return
        if not sliding and not _gust_safe(st, gc, pos(st)):
            return   # (caught in the open: go on, the next shelter is the nearest safety)
        st.update(); st.draw(); STATE["frames"] += 1


_GUST_IN = {"on": False}


def _gust_chain(st, goal):
    """Shelter to shelter (Mistralton Gym): the safe tiles to stop at on the way to goal, each hop short enough to walk
    in one calm between gusts. [] when goal is one hop away (or the room has no wind); None when no chain is found."""
    from src.world import gusts as _gu
    gc = _gu._cfg(st)
    if not gc:
        return []
    every, warn, blow = int(gc.get("every", 300)), int(gc.get("warn", 90)), int(gc.get("blow", 40))
    H = max(4, (every - warn - blow) // (STEP_GUST_FRAMES + 2) - 3)
    ppl = set(st._people())

    def opn(t):
        x, y = t
        return 0 <= y < st.h and 0 <= x < st.w and st.rows[y][x] == "." and t not in ppl and t not in st.exits

    def hop_from(s):
        seen, frontier, got = {s: 0}, [s], {}
        while frontier:
            nxt = []
            for x, y in frontier:
                for dx, dy in ((0, 1), (0, -1), (1, 0), (-1, 0)):
                    q = (x + dx, y + dy)
                    if q == goal:
                        got[goal] = seen[(x, y)] + 1
                    if q in seen or not opn(q) or seen[(x, y)] + 1 > H:
                        continue
                    seen[q] = seen[(x, y)] + 1
                    nxt.append(q)
                    if _gust_safe(st, gc, q):
                        got[q] = seen[q]
            frontier = nxt
        return got
    start = pos(st)
    prev, frontier = {start: None}, [start]
    while frontier and goal not in prev:
        nxt = []
        for s in frontier:
            for q in hop_from(s):
                if q not in prev:
                    prev[q] = s
                    nxt.append(q)
        frontier = nxt
    if goal not in prev:
        return None
    chain, t = [], goal
    while t != start:
        chain.append(t)
        t = prev[t]
    chain.reverse()
    return chain[:-1]


def _gust_hops(goal, why):
    """Walk shelter to shelter toward goal in a windy room, then let go() take the last hop."""
    for _try in range(80):
        st = settle()
        if not is_map(st) or not getattr(st, "gusts", None):
            return
        chain = _gust_chain(st, goal)
        if not chain:
            return
        _GUST_IN["on"] = True
        try:
            go(chain[0], why + " (shelter to shelter)")
        finally:
            _GUST_IN["on"] = False


def go(goal, why=""):
    """Walk to goal with real steps and walk into / onto it. -> (how it ended, steps walked):
    "arrived" (stood on it or walked into it), "left" (the walk onto it took you somewhere else: a way out),
    "moved" (something on the way took you elsewhere), "nopath", "gaveup"."""
    L0, n, blocked, fails, replans = loc(), 0, set(), collections.Counter(), 0
    goal = tuple(goal)
    if getattr(g.current_state, "gusts", None) and not _GUST_IN["on"]:
        _gust_hops(goal, why)   # (Mistralton Gym: shelter to shelter first)
    while True:
        st = settle()
        if not is_map(st) or loc() != L0:
            return "moved", n
        path = route(st, goal, False, blocked)
        if path is None:
            path = route(st, goal, True, blocked)
        if path is None:
            return "nopath", n
        if not path:
            return "arrived", n
        redo = False
        for k, (d, want) in enumerate(path):
            st = g.current_state
            if not is_map(st):
                st = settle()
            if getattr(st, "gusts", None):
                _gust_wait(st, path, k)
                if g.current_state is not st or pos(st) != (path[k - 1][1] if k else pos(st)) and k:
                    redo = True   # (blown off the path: plan again from where the wind left you)
                    break
            before, w0, s0 = pos(st), world(), len(said)
            try:
                st.facing = d
                st.step(*d)
            except Exception:
                crash(f"stepping {d} from {before} ({why})")
                fails[(before, d)] += 2
            st2 = settle()
            last = k == len(path) - 1
            if not is_map(st2) or loc() != L0:
                STATE["steps"] += 1
                return ("left" if last else "moved"), n + 1
            now = pos(st2)
            if now != before:
                n += 1
                STATE["steps"] += 1
            if want is None:   # (walked into it)
                if world() == w0 and len(said) == s0 and now == before and is_map(st2):   # (nothing: press the action key, as a player would)
                    try:
                        st2.facing = d
                        st2.handle_events([pygame.event.Event(pygame.KEYDOWN, key=pygame.K_SPACE, mod=0, unicode=" ")])
                    except Exception:
                        crash(f"pressing the action key at {now} ({why})")
                    settle()
                return "arrived", n
            if now != want:
                if last and now != before:   # (the walk onto it took you somewhere else on this map: a pad, a gate between two parts of one floor; 11-17)
                    return "left", n
                if now == before:
                    fails[(before, d)] += 1
                    if fails[(before, d)] >= 2 or (world() == w0 and len(said) == s0):
                        blocked.add((before, d))
                redo = True
                break
            if time.time() - T0 > TIME_LIMIT + 60:
                return "gaveup", n
        if not redo:
            return "arrived", n
        replans += 1
        if replans > 250:
            return "gaveup", n


# ---------------------------------------------------------------- the marker
def marker(st):
    """The Journal's gold marker on this map, as the game draws it: (tile, label) or None."""
    guide._CACHE.clear()   # (the game keeps the way for two seconds: a script runs faster than that)
    if is_town(st) and getattr(st, "_bar_list", None) and not st._busy():   # (and looks every third of a second at what a flag has opened: a quiz gate; 11-17)
        for _ in range(20):
            st._npc_tick()
    st._guide_key = None
    st._step_key = None
    try:
        return st._guide_spot()
    except Exception:
        crash("working out the Journal's marker")
        return None


# ---------------------------------------------------------------- wandering: what a child would try with no marker
def things(st):
    """(class, key, tiles, words, where it leads) for everything on this map you could try: 0 people, 1 doors / stairs /
    pads, 2 ways out to another area."""
    out_ = []
    area = st.area_key
    if is_town(st):
        mos = getattr(st, "motions", {})
        for home, opt in st.people.items():   # (by where they belong: people walk about)
            if not st._shown(opt) or (home in mos and mos[home].gone):
                continue
            spot = tuple(mos[home].pos) if home in mos else home
            now = next(o for o in opt["any"] if st._shown(o)) if "any" in opt else opt
            if str(now.get("action") or "").upper() in BORING or (now.get("event") or {}).get("name_rater") or (now.get("event") or {}).get("tutor"):
                continue
            if isinstance(now.get("event"), dict) and now["event"].get("stock"):   # (a shop made as an event - a store counter, a vending machine, a stall: a
                continue                                # shop screen the run can't leave, like the SHOP clerks; Sinnoh 11-24)
            _ride = (now.get("event") or {}).get("travel")   # (a ride - a ship, a ferry, a train - only toward the mission's place: else a
            if _ride and _ride != (MISSIONS.get(STATE.get("mission")) or {}).get("target"):   # run sails off and is stranded; Unova 11-23)
                continue
            out_.append((0, ("P", home), [spot], f"talk to {now.get('text')}", None))
        for t, kind in st.doors.items():
            room = st._room_for(t)
            opts = [o for o in st._door_options(kind) if str(o.get("action") or "").upper() not in BORING and not (o.get("event") or {}).get("name_rater") and not (o.get("event") or {}).get("tutor")]
            if room or opts:
                out_.append((1, ("D", t), [t], f"the {kind} door", (area, "room:" + room) if room else None))
        for t in set(getattr(st, "sign_events", None) or {}) | set(getattr(st, "sign_scenes", None) or {}):
            out_.append((1, ("S", t), [t], "a sign / machine", None))
        for t, bar in (getattr(st, "barred", None) or {}).items():   # (Johto: Cianwood Gym's red button: "The red button over there stops the waterfall")
            if isinstance(bar, dict) and bar.get("on_bump"):
                out_.append((1, ("S", t), [t], "a switch to press", None))
        for t in (getattr(st, "links", None) or {}):
            out_.append((1, ("W", t), [t], "a warp pad", None))
        for (t, _way), (to, _xy) in (st._guide_cocoons(getattr(st, "room", None)) if hasattr(st, "_guide_cocoons") else {}).items():
            out_.append((1, ("C", t, _way), [t], "a cocoon (its thread carries you on)", (area, "room:" + to if to else "outside")))   # (Castelia Gym; Unova 11-24)
        for tg, tiles in _stretches(st.exits):
            if tg.startswith("OUT:"):
                out_.append((1, ("X", tg, tiles[0]), tiles, "the way out of the building", (area, "outside")))
            elif tg.startswith("ROOM:"):
                out_.append((1, ("X", tg, tiles[0]), tiles, f"the stairs / door to {tg[5:]}", (area, "outside" if tg[5:] == "MAIN" else "room:" + tg[5:])))
            else:
                opt = st._travel_option(tg)
                shut = opt is None or not st._shown(opt)
                out_.append((3 if shut else 2, ("X", tg, tiles[0]), tiles, f"the way out to {tg}" + (" (the game says it's shut)" if shut else ""), None if shut else (tg, None)))
    else:
        f = st.run.floor
        i = st.run.index
        for m in f.movers:
            if m.kind == "figure" and isinstance(m.payload, dict):
                if str(m.payload.get("action") or "").upper() in BORING:
                    continue
                if isinstance(m.payload.get("event"), dict) and m.payload["event"].get("stock"):   # (a shop made as an event, as above)
                    continue
                out_.append((0, ("F", (m.x, m.y), str(m.payload.get("text"))), [(m.x, m.y)], f"walk up to {m.payload.get('text')}", None))
        rest, ways = {}, {}
        for t, tg in f.exits.items():
            if tg == core.STAIRS:
                ways[t] = "FLOOR:%d" % (i + 1)
            elif tg == core.STAIRS_UP:
                ways[t] = "FLOOR:%d" % (i - 1)
            elif str(tg).startswith("WARP:"):
                j = int(str(tg).split(":")[1])
                if j == i:
                    out_.append((1, ("X", t), [t], f"a warp pad ({tg})", None))
                else:
                    ways[t] = "FLOOR:%d" % j
            else:
                rest[t] = tg
        for tg, tiles in _stretches(ways):
            j = int(tg[6:])
            name = st._floor_name(j) if 0 <= j < st.run.n_floors else tg
            out_.append((1, ("X", tg, tiles[0]), tiles, f"the stairs / door to {name}", (area, "floor:%d" % j)))
        for tg, tiles in _stretches(rest):
            out_.append((2, ("X", tg, tiles[0]), tiles, f"the way out to {tg}", (tg, None)))
        for mv in f.movers:
            if mv.kind == "trainer":
                out_.append((1, ("T", (mv.x, mv.y)), [(mv.x, mv.y)], "a trainer", None))
        for t, dec in f.decor.items():
            dec = str(dec)
            if dec.startswith("door:"):
                out_.append((1, ("D", t), [t], f"the door ({dec[5:]})", None))
            elif dec.startswith("boulder:") and story.inventory.get("HM_STRENGTH", 0) > 0:
                out_.append((1, ("B", t), [t], "a boulder (Strength)", None))
            elif dec.startswith("whirl:") and story.inventory.get("HM_WHIRLPOOL", 0) > 0:
                out_.append((1, ("B", t), [t], "a whirlpool (Whirlpool)", None))
            elif dec.startswith("crack:") and __import__("src.world.hms", fromlist=["field"]).field(story, "HM_ROCK_SMASH"):
                out_.append((1, ("B", t), [t], "a cracked rock (Rock Smash)", None))
            elif dec == "statue" and (st._here_art() or {}).get("switch"):
                out_.append((1, ("Z", t), [t], "a statue's switch", None))
            elif dec == "secret" and "%d,%d" % tuple(t) in ((st._here_art() or {}).get("secret_switches") or {}):
                out_.append((1, ("Z", t), [t], "a secret switch", None))   # (batch 27: 5.7's island caves)
            elif dec and dec == str((st.recipe.get("gate") or {}).get("switch")):
                out_.append((1, ("Z", t), [t], f"the {dec} (something to check)", None))
            elif dec.startswith("barrier:") and (getattr(st, "_bars", {}).get(tuple(t)) or {}).get("boss"):
                out_.append((1, ("Z", t), [t], "something in the way that fights", None))
    return out_


def _stretches(exits):
    """A map's ways out as (target, [tiles]) for each separate stretch of tiles (Route 2 leaves Viridian Forest at both ends)."""
    left, out_ = dict(exits), []
    while left:
        t0, tg = next(iter(sorted(left.items())))
        todo, grp = [t0], []
        del left[t0]
        while todo:
            t = todo.pop()
            grp.append(t)
            for dx in (-1, 0, 1):
                for dy in (-1, 0, 1):
                    n = (t[0] + dx, t[1] + dy)
                    if n in left and left[n] == tg:
                        del left[n]
                        todo.append(n)
        out_.append((str(tg), sorted(grp)))
    return out_


TRIED = collections.Counter()   # (place, thing) -> times tried, with the story as it stands
DONE_PLACES = set()             # places with nothing left to try
MEM = {"world": None, "wander": 0, "skips": collections.Counter(), "stale": False, "looks": 0, "ask": {}}


def _nearest(st, tiles, prev):
    best = None
    for t in tiles:
        r = route(st, t, prev=prev)
        if r is not None and (best is None or len(r) < len(best[1])):
            best = (t, r)
    return best


def _words(m):
    return " " + guide._plain(" ".join(str(m.get(k) or "") for k in ("text", "desc", "title", "description"))) + " "


def _named(m, st, key, words):
    """Does the Journal's own text name this door or person (the Gym, the Poke Mart, the Captain)?"""
    text = _words(m)
    badge = "badges_less" in (m.get("condition") or {}) and not m.get("completed_flag")   # (a badge to win: the Gym, the Leader)
    if badge and key[0] == "D" and is_town(st) and st.doors.get(key[1]) == "gym":
        return True
    if badge and key[0] == "P" and is_town(st):
        opt = st.people.get(key[1]) or {}
        if any(str(o.get("action")).upper() == "GYM" for o in (opt.get("any") or [opt])):
            return True
    if key[0] == "D" and is_town(st):
        kind = str(st.doors.get(key[1], "")).lower()
        return len(kind) >= 3 and kind not in ("house", "home") and kind in text
    if key[0] == "X" and len(key) > 2 and key[1] in AREAS:
        name = guide._plain(AREAS[key[1]].get("route_name") or key[1].replace("_", " ").title())   # (Johto: no route_name on some)
        return len(name) >= 4 and (" " + name + " ") in text.replace(",", " ").replace(".", " ")
    if key[0] in "PF":
        who = guide._plain(words.replace("talk to ", "").replace("walk up to ", "")).strip()
        for w in ("talk to ", "visit ", "challenge ", "take "):
            who = who[len(w):] if who.startswith(w) else who
        clean = text
        for ch in ".,!:;":
            clean = clean.replace(ch, " ")
        clean = clean.replace("\u2019s ", " ").replace("'s ", " ")
        return len(who) >= 4 and (" " + who + " ") in clean
    return False


def _came_in(st):
    """The way you came in by counts as tried (you'd not turn straight round): the passage or way out beside you that
    leads back where you were."""
    L, was = loc(), MEM.get("was")
    MEM["was"] = L
    if was is None or was == L:
        return
    p = pos(st)
    for cls, key, tiles, words, dest in things(st):
        if dest is None or not (dest == was or (dest[1] is None and dest[0] == was[0] and was[0] != L[0])):
            continue
        if min(abs(t[0] - p[0]) + abs(t[1] - p[1]) for t in tiles) <= 2:
            if not TRIED[(L, key)]:
                TRIED[(L, key)] = 1
            BACK.add((L, key))
            if was[0] != L[0]:
                TRAIL.clear()
            elif cls == 1 and not MEM.pop("backing", False):   # (the way back, for when this part of the place has nothing left)
                TRAIL.append((L, key, min(tiles, key=lambda t: abs(t[0] - p[0]) + abs(t[1] - p[1]))))
            break


BACK = set()   # (place, thing): the ways you came in by
TRAIL = []     # the passages you came through inside this place, last one last: the way back out of a dead end


def search_cans(st):
    """A Gym's trash cans (FireRed's Vermilion Gym: two switches under them, the second beside the first): walk into them
    one after another, as the Gym Guide tells you to, till the Leader's door opens. -> what was done, or None."""
    tc = (((st.town_map or {}).get("rooms") or {}).get(st.room) or {}).get("trashcans") if is_town(st) and st.room else None
    fl = story.story_flags
    if not tc or fl.get(tc["open"]):
        return None
    cans, cols = [tuple(c) for c in tc["cans"]], int(tc.get("cols", 5))
    row, n0 = None, MEM.get("cans", 0)
    for n in range(400):
        st = g.current_state
        if not is_town(st) or fl.get(tc["open"]):
            break
        if fl.get(tc["first"]):   # (one lock open: the switch is in a can beside that one)
            i = MEM.get("can_first", 0)
            r, c = divmod(i, cols)
            near = [rr * cols + cc for rr, cc in ((r - 1, c), (r + 1, c), (r, c - 1), (r, c + 1)) if 0 <= cc < cols and 0 <= rr and rr * cols + cc < len(cans)]
            j = near[MEM.get("can_near", 0) % len(near)]
            MEM["can_near"] = MEM.get("can_near", 0) + 1
        else:
            j = MEM.get("can_scan", 0) % len(cans)
            MEM["can_scan"] = MEM.get("can_scan", 0) + 1
        was = bool(fl.get(tc["first"]))
        row = do("puzzle", cans[j], f"search trash can {j + 1} of {len(cans)}")
        MEM["cans"] = MEM.get("cans", 0) + 1
        if row["how"] == "nopath":
            continue
        if not was and fl.get(tc["first"]):
            MEM["can_first"] = j
    STATE["puzzles"] += 1
    return row


def push_drops(st):
    """A floor's boulders that drop through its holes onto the floor below (dungeon._drops: the Ice Path's B1F): walk into
    each not yet pushed, nearest first. -> what was done, or None."""
    if not is_dun(st) or story.inventory.get("HM_STRENGTH", 0) <= 0:
        return None
    L, best = loc(), None
    for b, _hole, _land in st._drops(st.run.index):
        b = tuple(b)
        if story.story_flags.get(st._boulder_flag(b)) or TRIED[(L, ("DROP", b))] >= 2:
            continue
        r = route(st, b)
        if r is not None and (best is None or len(r) < best[1]):
            best = (b, len(r))
    if best is None:
        return None
    TRIED[(L, ("DROP", best[0]))] += 1
    STATE["puzzles"] += 1
    return do("puzzle", best[0], f"push the boulder at {best[0]} into its hole (it drops to the floor below)")


def talk_companions(st):
    """Someone walking with you (Lance in the Rocket hideout) with a line on this floor not heard yet (an unset flag):
    turn to them and press the action key (the game's own _talk_companion, as the key does). -> True if talked."""
    if not is_dun(st):
        return False
    try:
        names = st._companions()
    except Exception:
        return False
    if not names:
        return False
    from src.states.overworld.dungeon import _flat_people
    art = (st.run.recipe or {}).get("art") or {}
    fl = art["floors"][st.run.index] if art.get("floors") and st.run.index < len(art["floors"]) else art
    for who in names:
        item = next((p for p in _flat_people(fl.get("people")) if isinstance(p, dict) and str(p.get("text", "")).strip() == who
                     and st.npc_shown(p)), None)
        flag = ((item or {}).get("event") or {}).get("flag")
        key = (loc(), ("C", who))
        if not item or not flag or story.story_flags.get(flag) or TRIED[key] >= 1:
            continue
        TRIED[key] += 1
        a, s0, at0 = snap(), len(said), here()
        try:
            st._talk_companion(who)
        except Exception:
            crash(f"talking to {who} walking with you")
        settle()
        got = gained(a, snap())
        ROWS.append({"n": len(ROWS) + 1, "mission": STATE["mission"], "kind": "wander", "from": at0, "to": None, "label": None,
                     "what": f"turn and talk to {who} (walking with you)", "how": "arrived", "steps": 0, "now": here(), "gained": got,
                     "said": said[s0:][:8]})
        out(f"  {len(ROWS):4d} [{STATE['mission']}] wander: turn and talk to {who} (walking with you) @ {at0}" + (f" | {got}" if got else ""))
        return True
    return False


def wander(st, m, stay=True):
    """Try the nearest thing here not tried yet: what the Journal's words name first, then people, then doors and stairs
    (stay: not the ways out to other areas). Nothing new: on to a part of this place that still has something.
    -> what was done, or None."""
    row = search_cans(st)
    if row is not None:
        return row
    row = push_drops(st)
    if row is not None:
        return row
    L = loc()
    prev = flood(st)
    prev2 = None
    best = None
    every = things(st)
    for cls, key, tiles, words, dest in every:
        named = _named(m, st, key, words)
        if TRIED[(L, key)] >= 1 or (stay and cls >= 2 and not named and key[1] != "BOSS"):
            continue
        hit = _nearest(st, tiles, prev)
        if hit is None and cls < 2:   # (behind a trainer or a boulder)
            prev2 = prev2 if prev2 is not None else flood(st, True)
            hit = _nearest(st, tiles, prev2)
        if hit is None:
            continue
        score = (0 if named else 1, cls, len(hit[1]))
        if best is None or score < best[0]:
            best = (score, key, hit[0], words)
    if best is None:   # nothing new here: on to somewhere in this place that still has something
        DONE_PLACES.add(L)
        for cls, key, tiles, words, dest in every:
            if dest is None or dest == L or dest in DONE_PLACES or (stay and dest[0] != L[0]) \
                    or (dest[1] is None and not stay and any(q[0] == dest[0] for q in DONE_PLACES)):
                continue
            hit = _nearest(st, tiles, prev)
            if hit is not None and (best is None or len(hit[1]) < best[0][2]):
                best = ((9, 9, len(hit[1])), key, hit[0], words + " (nothing left to try here)")
        if best is None:
            return None
    _, key, tile, words = best
    s0 = len(said)
    row = do("wander", tile, words)
    if MEM.pop("retry_here", False):   # (it hung, and the script freed it: the same thing once more)
        return row
    TRIED[(L, key)] += 1 if (len(said) > s0 or key[0] not in "PF" or row["how"] != "arrived") else 0.5   # (someone who walked off before you got there: once more)
    return row


# ---------------------------------------------------------------- going by the Journal's words: the way to a named place
_TM = json.load(open("assets/town_maps.json", encoding="utf-8"))


def _map_graph():
    """Area -> the areas its walked map leads to (its own ways out, its rooms' and floors'; a door that is a way to
    another area: the harbour's ship, the Game Corner)."""
    gr = collections.defaultdict(set)
    for k, m in _TM.items():
        if k not in AREAS or not isinstance(m, dict):
            continue
        parts = [m] + list((m.get("rooms") or {}).values()) + list(m.get("floors") or [])
        for part in parts:
            if not isinstance(part, dict):
                continue
            for tg in (part.get("exits") or {}).values():
                if isinstance(tg, str) and tg in AREAS and tg != k:
                    gr[k].add(tg)
            for room in (part.get("rooms") or {}).values():
                for tg in ((room or {}).get("exits") or {}).values():
                    if isinstance(tg, str) and tg in AREAS and tg != k:
                        gr[k].add(tg)
    for k, a in AREAS.items():
        if not isinstance(a, dict):
            continue
        for o in (a.get("travel_options") or []) + (a.get("explore_options") or []) + (a.get("route_menu") or []):
            tg = (o.get("target_area") if o.get("door") else None) or (guide.leads_to(g, k, o) if o.get("action") == "GAMECORNER" or o.get("door") else None)
            if tg and tg in AREAS and tg != k:
                gr[k].add(tg)
    return gr


MAPG = _map_graph()
SHUT = collections.Counter()   # (area, next area): times the game refused that way out, with the story as it stands


def map_path(a, b):
    """The areas from a to b over the walked maps' own ways out (not the ones the game has just refused)."""
    prev, q = {a: None}, deque([a])
    while q:
        cur = q.popleft()
        if cur == b:
            out_ = [cur]
            while prev[out_[-1]] is not None:
                out_.append(prev[out_[-1]])
            return out_[::-1]
        for n in sorted(MAPG.get(cur, ())):
            if n not in prev and SHUT[(cur, n)] < 2:
                prev[n] = cur
                q.append(n)
    return None


def _door_to(st, t):
    """The other area a town's door leads to (the harbour's ship, the Game Corner), if any."""
    for o in st._door_options(st.doors[t]):
        tg = guide.leads_to(g, st.area_key, o) or (o.get("target_area") if o.get("door") else None)
        if tg:
            return tg
    return None


def place_dist(st, nxt):
    """{room or floor: how many passages from it to one with a way out to nxt} (the game's own map data), so the nearest
    passage toward the way out is tried first (off the S.S. Anne: the gangway, not every cabin)."""
    adj, goal = collections.defaultdict(set), set()
    if is_town(st):
        tm = st.town_map or {}
        parts = {"outside": tm}
        parts.update({"room:" + n: r for n, r in (tm.get("rooms") or {}).items()})
        for name, part in parts.items():
            for tg in (part.get("exits") or {}).values():
                tg = str(tg)
                if tg.startswith("OUT:"):
                    adj[name].add("outside")
                elif tg.startswith("ROOM:"):
                    adj[name].add("outside" if tg[5:] == "MAIN" else "room:" + tg[5:])
                elif tg == nxt:
                    goal.add(name)
        for door, room in (tm.get("inside") or {}).items():
            adj["outside"].add("room:" + room)
    else:
        run = st.run
        for i in range(run.n_floors):
            f, name = run.made(i), "floor:%d" % i
            for tg in f.exits.values():
                if tg == core.STAIRS:
                    adj[name].add("floor:%d" % (i + 1))
                elif tg == core.STAIRS_UP:
                    adj[name].add("floor:%d" % (i - 1))
                elif str(tg).startswith("WARP:"):
                    adj[name].add("floor:" + str(tg).split(":")[1])
                elif tg == nxt:
                    goal.add(name)
    dist, q = {x: 0 for x in goal}, deque(goal)
    while q:
        cur = q.popleft()
        for a_, outs in adj.items():
            if cur in outs and a_ not in dist:
                dist[a_] = dist[cur] + 1
                q.append(a_)
    return dist


def _back_doors(st):
    """A town's buildings you can walk through (two ways out to different spots: Cerulean's burgled house)."""
    tm = st.town_map or {}
    return {n for n, r in (tm.get("rooms") or {}).items() if len({str(v) for v in (r.get("exits") or {}).values() if str(v).startswith("OUT:")}) > 1}


def step_to_next(st, m, here_a, nxt, area, kind="words", label=None):
    """One move toward the next area: its way out if you can get to it, else a passage of this place (the one that leads
    toward that way out first), else whoever / whatever stands in the way. -> what was done, or None."""
    row = push_drops(st)
    if row is not None:
        return row
    L = loc()
    prev = flood(st)
    prev2 = flood(st, True)
    dist = place_dist(st, nxt)
    through = _back_doors(st) if is_town(st) and not st.room else set()
    outs, inner, block, other, last = [], [], [], [], []
    for cls, key, tiles, words, dest in things(st):
        to_nxt = (key[0] == "X" and len(key) > 2 and key[1] == nxt) or (key[0] == "D" and is_town(st) and _door_to(st, key[1]) == nxt)
        hit = _nearest(st, tiles, prev) or _nearest(st, tiles, prev2)
        if hit is None:
            continue
        if to_nxt and (L, key) in BACK and here_a != area and is_dun(st) and st.run.n_floors > 1:   # (a cave's way in, the one you came by: last of all)
            last.append((TRIED[(L, key)], len(hit[1]), key, hit[0], words))
        elif to_nxt:
            outs.append(((L, key) in BACK, TRIED[(L, key)], len(hit[1]), key, hit[0], words))
        elif cls == 2 and key[1] in AREAS and TRIED[(L, key)] < 1 and (L, key) not in BACK:
            other.append((len(hit[1]), key, hit[0], words))
        elif key[0] == "X" and len(key) > 2 and key[1] == "BOSS" and TRIED[(L, key)] < 1:
            block.append((0, len(hit[1]), key, hit[0], "whatever is asleep in the way"))
        elif cls == 1 and key[0] not in "TSZ" and TRIED[(L, key)] < 1 and (dest is None or dest[0] == here_a):
            d = dist.get(dest[1], 50) if dest else 60
            if dest and dest[1].startswith("room:") and dest[1][5:] in through:
                d = -1
            inner.append((d, len(hit[1]), key, hit[0], words))
        elif cls == 0 and TRIED[(L, key)] < 1:
            block.append((1, len(hit[1]), key, hit[0], words + " (in the way?)"))
        elif key[0] in "BZ" and TRIED[(L, key)] < 1:
            block.append((2, len(hit[1]), key, hit[0], words))
    tag = f"toward {area}" if kind == "words" else f"the marker's way out ({nxt})"
    if outs and SHUT[(here_a, nxt)] < 2:
        _, _, _, key, tile, words = min(outs)
        row = do(kind, tile, f"{tag}: {words}", label)
        TRIED[(L, key)] += 1
        st2 = g.current_state
        if is_map(st2) and loc() == L and row["how"] in ("nopath", "arrived", "gaveup"):   # (the game didn't let you through)
            why = next((x for x in reversed(row["said"]) if x and not x.startswith("[")), "")
            left = [mv for mv in st2.run.floor.movers if mv.kind == "trainer"] if is_dun(st2) else []
            hit = _nearest(st2, [(mv.x, mv.y) for mv in left], flood(st2)) if left else None
            if hit and "trainer" in why.lower():   # (it said so: beat the trainers here first)
                return do(kind, hit[0], f"{tag}: battle a trainer still standing here (the way out wouldn't open)", label)
            SHUT[(here_a, nxt)] += 1
            GATES.append({"mission": m.get("id"), "where": here(), "from": here_a, "to": nxt, "said": why, "kind": kind,
                          "badges": len(story.badges.get("UNOVA", []))})
            out(f"  .... the way from {here_a} to {nxt} is shut: {why[:140]}")
        return row
    if inner:
        _, _, key, tile, words = min(inner)
        row = do(kind, tile, f"{tag} (looking for the way to {nxt}): {words}", label)
        TRIED[(L, key)] += 1
        return row
    block = [b_ for b_ in block if b_[0] != 1 or MEM["ask"].get(L, 0) < 6]   # (asking round: the six nearest people at most)
    if block and not outs:
        _, _, key, tile, words = min(block)
        s0, w0 = len(said), world()
        row = do(kind, tile, f"{tag} (no way on from here): {words}", label)
        TRIED[(L, key)] += 1 if (len(said) > s0 or row["how"] != "arrived") else 0.5
        if key[0] in "PF":
            MEM["ask"][L] = MEM["ask"].get(L, 0) + 1
        if key[1] == "BOSS" and world() == w0 and is_map(g.current_state) and loc() == L:   # (it won't budge: this way is shut for now)
            why = next((x for x in reversed(row["said"]) if x and not x.startswith("[")), "")
            SHUT[(here_a, nxt)] += 2
            TRIED[(L, key)] = 1
            GATES.append({"mission": m.get("id"), "where": here(), "from": here_a, "to": nxt, "said": why, "kind": kind,
                          "badges": len(story.badges.get("UNOVA", []))})
            out(f"  .... the way from {here_a} to {nxt} is shut: {why[:140]}")
        return row
    if other and not outs and not (last and not is_dun(st)):   # (no way to that way out from this part of the place: round by another area)
        known = part_way(st, area) or part_way(st, nxt)   # (to the place itself, else on to the next place on the way)
        if known is not None and (_nearest(st, [known], prev) or _nearest(st, [known], prev2)):   # (a way round walked before)
            return do(kind, known, f"{tag} (no way to {nxt} from this side: round by the way walked before)", label)
        _, key, tile, words = min(other)
        row = do(kind, tile, f"{tag} (no way to {nxt} from this side: round by) {words}", label)
        TRIED[(L, key)] += 1
        return row
    if last and SHUT[(here_a, nxt)] < 2:
        _, _, key, tile, words = min(last)
        row = do(kind, tile, f"{tag}: back out by {words}", label)
        TRIED[(L, key)] += 1
        if is_map(g.current_state) and loc() == L:
            SHUT[(here_a, nxt)] += 1
        return row
    # every passage here tried: a dead end; back the way you came
    while TRAIL and TRAIL[-1][0] != L:
        TRAIL.pop()
    while TRAIL and TRAIL[-1][0] == L:
        _, key, tile = TRAIL.pop()
        if route(st, tile, prev=prev) is not None or route(st, tile, prev=prev2) is not None:
            MEM["backing"] = True
            return do(kind, tile, f"{tag} (a dead end: back the way you came)", label)
    again = []   # (no trail left: a passage of this place used before, the least used first)
    for cls, key, tiles, words, dest in things(st):
        if cls == 1 and dest is not None and dest[0] == here_a and dest != L and TRIED[(L, key)] < 4:
            hit = _nearest(st, tiles, prev) or _nearest(st, tiles, prev2)
            if hit:
                again.append((TRIED[(L, key)], dist.get(dest[1], 50), len(hit[1]), key, hit[0], words))
    if again:
        _, _, _, key, tile, words = min(again)
        TRIED[(L, key)] += 1
        MEM["backing"] = True
        return do(kind, tile, f"{tag} (nothing new here: back by) {words}", label)
    return None


def head_for(st, m, area):
    """One move toward a named area the marker isn't leading to (see step_to_next). None: no way known over the maps, or
    everything tried."""
    here_a = st.area_key
    for _ in range(6):
        path = map_path(here_a, area)
        if not path or len(path) < 2:
            known = part_way(st, area)   # (no way over the maps' areas: a way the run walked before, part to part)
            return do("words", known, f"toward {area}: the way walked before") if known is not None else None
        row = step_to_next(st, m, here_a, path[1], area)
        if row is not None:
            return row
        SHUT[(here_a, path[1])] += 2   # (no way to that way out from here: another way round, if the maps have one)
    return None


GATES = []   # ways out the game refused while the script was heading somewhere by the Journal's words


# ---------------------------------------------------------------- one thing done, written down
def do(kind, tile, words, label=None):
    m = STATE["mission"]
    a, s0, at0 = snap(), len(said), here()
    p0 = part_of(g.current_state)
    how, n = go(tile, words)
    b = snap()
    p1 = part_of(g.current_state)
    if p0 and p1 and p0[:2] != p1[:2]:   # (a move into another place or room: written down for part_way)
        PART_EDGE[p0][tuple(tile)] = p1
        st1 = g.current_state   # (and the way back: the way out beside where you arrived that leads back there)
        ex = st1.exits if is_town(st1) else st1.run.floor.exits
        at = pos(st1)
        back = [t for t, tg in ex.items() if str(tg) == p0[0] and abs(t[0] - at[0]) + abs(t[1] - at[1]) <= 1]
        if back and back[0] not in PART_EDGE[p1]:
            PART_EDGE[p1][back[0]] = p0
    got = gained(a, b)
    heard = [x for x in said[s0:] if not x.startswith("(")][:3]
    row = {"n": len(ROWS) + 1, "mission": m, "kind": kind, "from": at0, "to": list(tile), "label": label, "what": words, "how": how,
           "steps": n, "now": here(), "gained": got, "said": said[s0:][:8]}
    ROWS.append(row)
    if m in PER:
        PER[m]["steps"] += n
        PER[m]["acts"] += 1
        PER[m]["wander"] += kind != "marker"
        if got:
            PER[m]["gained"].append(got)
    out(f"  {row['n']:4d} [{m}] {kind}: {words}{' <' + label + '>' if label else ''} @ {at0} -> {tuple(tile)}: {how}, {n} steps, now {row['now']}"
        + (f" | {got}" if got else "") + (f" | \"{' / '.join(heard)[:150]}\"" if heard else ""))
    return row


def gap(what, extra=None):
    """A Journal gap that didn't stop the run (the script wandered on)."""
    key = (STATE["mission"], loc(), what)
    if any(f.get("key") == key for f in FIND):
        return
    FIND.append({"kind": "GAP", "key": key, "mission": STATE["mission"], "where": here(), "what": what, "extra": extra})
    out(f"  .... gap [{STATE['mission']}] at {here()}: {what}")


# ---------------------------------------------------------------- stuck: write it down, then the smallest skip
BADGE_ORDER = [("ASPERTIA_CITY", "BASIC"), ("VIRBANK_CITY", "TOXIC"), ("CASTELIA_CITY", "INSECT"), ("NIMBASA_CITY", "BOLT"),
               ("DRIFTVEIL_CITY", "QUAKE"), ("MISTRALTON_CITY", "JET"), ("OPELUCID_CITY", "LEGEND"), ("HUMILAU_CITY", "WAVE")]
# (Black 2's Gym order)


def objective(m):
    """Where a mission is really done, from the game's data (what a walkthrough would tell you): an area."""
    c = m.get("condition") or {}
    if c.get("visited_not"):
        return c["visited_not"]
    if m.get("targets"):
        return guide.mission_target(g, m)
    for s in m.get("steps") or []:
        if not guide._ok(story, s.get("done")):
            return s.get("area") or guide.mission_target(g, m)
    t = guide.mission_target(g, m)
    if t:
        return t
    if "badges_less" in c:
        return BADGE_ORDER[min(len(story.badges.get("UNOVA", [])), 7)][0]
    if m.get("id") == "b2_m_league":   # (batch 10: the League's mission id, when it's written)
        return "UNOVA_POKEMON_LEAGUE"
    return None


def put_at(area):
    """A skip: stand the player at an area's way in (as walking in from the nearest area on the way there)."""
    came = None
    try:
        p = guide.path_to(g, story.current_area_key, area)
        came = p[-2] if p and len(p) > 1 else None
    except Exception:
        pass
    if came is None:
        came = next(iter(guide.neighbours(g, area, False)), story.current_area_key)
    story.last_area_key = story.current_area_key
    story.current_area_key, story.last_area_key = area, came
    g.walk_town_pos = None
    g.walk_town_room = None
    g.walk_town_exit = None
    st = CityState(g) if AREAS[area].get("area_type") == "town" else None
    if st is None or not isinstance(st, _WTS):
        st = PlayState(g); g.states["play"] = st
    g.change_state(st)
    settle()
    return came


def force(m):
    """The last resort: the mission's own end, set by hand (written down as the whole mission skipped)."""
    c = m.get("condition") or {}
    done = []
    for f in story.mission_flags(m):
        if not story.story_flags.get(f):
            story.story_flags[f] = True
            done.append("flag " + f)
    if not done and c.get("visited_not"):
        story.story_flags["visited_" + c["visited_not"]] = True
        done.append("flag visited_" + c["visited_not"])
    if not done and "badges_less" in c:
        town, badge = BADGE_ORDER[min(len(story.badges.get("UNOVA", [])), 7)]
        story.badges.setdefault("UNOVA", []).append(badge)
        from src.world import hms
        hms.give_for_badges(story)
        done.append(f"badge {badge} (with its HM, if any)")
    if not done and c.get("item_not"):
        its = c["item_not"] if isinstance(c["item_not"], list) else [c["item_not"]]
        story.inventory[its[0]] = 1
        done.append("item " + its[0])
    if not done and c.get("flag_not"):
        fl = c["flag_not"] if isinstance(c["flag_not"], list) else [c["flag_not"]]
        story.story_flags[fl[0]] = True
        done.append("flag " + fl[0])
    return done


def obstacles(st):
    """What stands on this map that needs a move or an item, and which of those you hold (for a stuck point's write-up)."""
    try:
        if is_dun(st):
            c = collections.Counter(str(v).split(":")[0] for v in st.run.floor.decor.values())
            c = {k: n for k, n in c.items() if k in ("boulder", "cut", "crack", "falls", "barrier", "rubble", "whirl", "slope", "stones", "climb", "crate", "hole", "pressed")}
            f = st.run.floor
            if any(f.tile(x, y) == core.SURF for y in range(f.h) for x in range(f.w)):
                c["sea"] = 1
        elif is_town(st):
            g_ = "".join(getattr(st, "grid", []) or [])
            c = {k: g_.count(ch) for k, ch in (("cut tree", "2"), ("cracked rock", "0"), ("muddy slope", "7")) if g_.count(ch)}
            if getattr(st, "barred", None):
                c["someone / something barring a tile"] = len(st.barred)
        else:
            c = {}
    except Exception:
        c = {}
    held = sorted(k for k, v in story.inventory.items() if v and (k.startswith("HM_") or k in ("BICYCLE", "XTRANSCEIVER", "TOWN_MAP", "DROPPED_ITEM", "PROP_CASE", "DOWSING_MACHINE")))
    return f"on this map: {c or 'nothing that needs a move'}; held: {held or 'no HM or key item'}"


def stuck(why, m, spot):
    mid = m.get("id") if m else None
    fn = shot(f"STUCK_{mid}")
    level = MEM["skips"][mid]
    MEM["skips"][mid] += 1
    rec = {"kind": "STUCK", "mission": mid, "title": (m or {}).get("text"), "journal": (m or {}).get("desc"), "where": here(),
           "marker": f"{spot[1]} at {tuple(spot[0])}" if spot else "none", "why": why, "shot": fn, "here": obstacles(g.current_state),
           "badges": len(story.badges.get("UNOVA", [])), "gates": [x for x in GATES if x["mission"] == mid][-6:],
           "tried": [f"{r['kind']}: {r['what']} -> {r['how']}" for r in ROWS[-10:] if r["mission"] == mid]}
    area = objective(m) if m else None
    skip = None
    if m is None and level == 0 and len(story.badges.get("UNOVA", [])) < 8:
        town = BADGE_ORDER[len(story.badges.get("UNOVA", []))][0]
        came = put_at(town)
        skip = f"put the player at {town}, the next Gym's town (as if walked in from {came})"
    elif m is None:
        skip = "none possible: the Journal shows no MAIN mission; the run ends here"
    elif level == 0 and area and area in AREAS and area != story.current_area_key:
        came = put_at(area)
        skip = f"put the player at {area} (as if walked in from {came})"
    elif level <= 1 and area and area in AREAS and (m.get("steps") or level == 0):
        s = next((s for s in m.get("steps") or [] if not guide._ok(story, s.get("done")) and (s.get("area") or area) == area), None)
        came = put_at(area)
        skip = f"put the player at {area} again (as if walked in from {came})"
        st = g.current_state
        if s and is_dun(st) and s.get("floor") is not None and 0 <= s["floor"] < st.run.n_floors:
            f = st.run.made(s["floor"])
            spot2 = next(((s["at"][0] + dx, s["at"][1] + dy) for dx, dy in DIRS if f.walkable(s["at"][0] + dx, s["at"][1] + dy)
                          and f.mover_at(s["at"][0] + dx, s["at"][1] + dy) is None), None)
            if spot2:
                st._warp(s["floor"], *spot2, land=True)
                st.run.player = spot2
                skip = f"put the player on {area} floor {s['floor']} beside the step's own spot {tuple(s['at'])} ({s.get('label')})"
                settle()
    else:
        done = force(m)
        skip = ("set by hand: " + ", ".join(done) + " (the whole mission skipped)") if done else "none found"
    rec["skip"] = skip
    FIND.append(rec)
    if mid in PER:
        PER[mid]["stuck"] += 1
        PER[mid]["skips"].append(skip)
    print(f"FAIL STUCK [{mid} {(m or {}).get('text')}] at {rec['where']}: {why} | marker: {rec['marker']} | skip: {skip} | {fn}", flush=True)
    TRIED.clear(); DONE_PLACES.clear(); BACK.clear(); SHUT.clear(); TRAIL.clear(); MEM["wander"] = 0; MEM["stale"] = False; MEM["was"] = None
    return skip


# ---------------------------------------------------------------- the playthrough
GOAL = "beat_unova_champion"   # (the League's Champion, Iris: her victory_flag)
CHAMPION_FLAG = "beat_unova_champion"
SEVII_TOO = False


def _the_end():
    """The run's goal: the Champion beaten."""
    if story.story_flags.get(CHAMPION_FLAG) and not STATE.get("champion_at"):
        STATE["champion_at"] = round(time.time() - T0)
        print(f"== MILESTONE: Iris beaten, Unova Champion at {STATE['champion_at']} s | at {here()}", flush=True)
    return "CHAMPION" if story.story_flags.get(GOAL) else None


def play_through():
    last_id = "?"
    ticks = 0
    ended = "ran out of turns"
    while True:
        ticks += 1
        if _the_end():
            ended = "CHAMPION"
            break
        if time.time() - T0 > TIME_LIMIT:
            ended = "ran out of time"
            break
        if ticks > 6000:
            break
        st = settle()
        if _the_end():
            ended = "CHAMPION"
            break
        if not is_map(st):
            _back_out(st, "not a map after settling")
            continue
        m = mission()
        mid = m.get("id") if m else None
        if mid != last_id:
            if _not_built(mid):   # (the batches not built yet start here: the run ends, passed - save points, above)
                if last_id in PER:
                    PER[last_id]["ended"] = here()
                    PER[last_id]["done"] = True
                ended = f"built so far: reached {mid}, not built yet"
                print(f"== STOP {mid}: {(m or {}).get('title') or (m or {}).get('text')} is in a batch not built yet | at {here()} | {round(time.time() - T0)} s", flush=True)
                break
            _save_point(mid)
            STATE["mission"] = mid
            if mid is not None and mid not in PER:
                PER[mid] = {"id": mid, "title": m.get("text"), "desc": m.get("desc"), "target": guide.mission_target(g, m), "started": here(),
                            "steps": 0, "acts": 0, "wander": 0, "stuck": 0, "skips": [], "gained": [], "markers": [], "order": len(PER) + 1,
                            "badges": len(story.badges.get("UNOVA", [])), "t": round(time.time() - T0)}
            fn = shot(f"{mid}")
            if mid in PER:
                PER[mid].setdefault("shots", []).append(fn)
            if last_id in PER:
                PER[last_id]["ended"] = here()
                PER[last_id]["done"] = True
            print(f"== MISSION {mid}: {(m or {}).get('text')} | at {here()} | badges {len(story.badges.get('UNOVA', []))} | {round(time.time() - T0)} s | {fn}", flush=True)
            if m:
                out(f"   Journal: {str(m.get('desc'))[:300]}")
            last_id = mid
            TRIED.clear(); DONE_PLACES.clear(); BACK.clear(); SHUT.clear(); MEM["wander"] = 0; MEM["stale"] = False; MEM["looks"] = 0; MEM["ask"] = {}
        w = world()
        if w != MEM["world"]:   # (the story moved: the marker counts again, and what was tried may be worth a second look)
            MEM["world"] = w
            for k in [k for k in TRIED if k[1][0] == "M"]:
                del TRIED[k]
            DONE_PLACES.clear(); MEM["wander"] = 0; MEM["stale"] = True; MEM["mk"] = 0
            SHUT.clear()
        if m is None:
            if stuck("the Journal shows no MAIN mission", None, None).startswith("none"):
                ended = "no MAIN mission"
                break
            continue
        L = loc()
        _came_in(st)
        if push_drops(st) is not None:   # (the Ice Path's boulders before the marker: on B1F it points back up to 1F)
            continue
        if talk_companions(st):   # (Lance walking with you in the hideout: his Whirlpool line)
            continue
        spot = marker(st)
        if spot:
            tile, label = tuple(spot[0]), spot[1]
            desc = f"{L[0]} {L[1]} {tile} '{label}'"
            if desc not in PER[mid]["markers"]:
                PER[mid]["markers"].append(desc)
            ex = (st.exits if is_town(st) else st.run.floor.exits).get(tile)
            to_area = ex if isinstance(ex, str) and ex in AREAS else None
            key = (L, ("M", to_area or tile, label))   # (with its words: the same tile can ask for something new - Icefall's cracked ice, 11-17)
            if TRIED[key] < 1 and to_area:
                _ex = st.exits if is_town(st) else st.run.floor.exits
                _gr = [(tg_, tl_) for tg_, tl_ in _stretches(_ex) if tg_ == to_area]
                _mine = next(((tg_, tl_) for tg_, tl_ in _gr if tile in tl_), None)
                _other = [tl_ for tg_, tl_ in _gr if _mine and tl_ is not _mine[1] and (L, ("X", tg_, tl_[0])) not in BACK]
                if _mine and (L, ("X", _mine[0], _mine[1][0])) in BACK and _other and _nearest(st, _other[0], flood(st)):
                    gap(f"the marker ('{label}' at {tile}) points back out the way you came in, though another way out of here also goes to {to_area}")
                    TRIED[key] += 1
                    do("words", _nearest(st, _other[0], flood(st))[0], f"the other way out to {to_area} (the marker pointed back the way you came)", label)
                    continue
            if TRIED[key] < 1:
                if to_area and SHUT[(L[0], to_area)] >= 2:
                    TRIED[key] += 1
                    gap(f"the marker ('{label}') leads to {to_area}, and that way is shut from here")
                    continue
                if to_area and route(st, tile) is None and route(st, tile, True) is None:
                    # (its tile can't be walked to from here: another tile of that way out, or through the gatehouse / cave between)
                    row = step_to_next(st, m, L[0], to_area, to_area, kind="marker", label=label)
                    if row is None:
                        TRIED[key] += 1
                        gap(f"the marker ('{label}' at {tile}) is on a way out that can't be reached from {here()}")
                    else:
                        MEM["mk"] = MEM.get("mk", 0) + 1
                        if MEM["mk"] > 3 * XBUDGET:
                            TRIED[key] += 1
                    continue
                row = do("marker", tile, "follow the marker", label)
                TRIED[key] += 1 if row["how"] in ("arrived", "left", "nopath", "gaveup") else 0.34
                if row["how"] == "nopath":
                    gap(f"the marker ('{label}' at {tile}) is on a tile that can't be walked to from {row['from']}")
                continue
            gap(f"the marker ('{label}' at {tile}) was followed and nothing in the story changed")
        else:
            gap("no marker on this map" + (" (inside a building)" if L[1].startswith("room:") else ""))
        # the marker didn't help: go by the Journal's words (the place it names), then look round there
        MEM["wander"] += 1
        if MEM["wander"] > XBUDGET:
            stuck(f"{XBUDGET} things tried without the marker and nothing in the story moved", m, spot)
            continue
        area = objective(m)
        row = None
        if area and area in AREAS and area != L[0]:
            row = head_for(st, m, area)
            if row is None and L[1].startswith("room:"):   # (in a building: out of it first)
                row = wander(st, m, stay=True)
            if row is not None:
                PER[mid]["words"] = PER[mid].get("words", 0) + 1
                continue
            stuck(f"no way found to {area} (the place the Journal's words name) over the maps as they stand", m, spot)
            continue
        row = wander(st, m, stay=True)
        if row is None:
            if MEM["stale"] and MEM["looks"] < 2:   # (things changed since these were tried: once more round)
                MEM["stale"] = False; MEM["looks"] += 1
                TRIED.clear(); DONE_PLACES.clear(); BACK.clear()
                continue
            stuck("nothing left to try here that can be reached", m, spot)
    return ended


ENDED = "crashed"
try:
    ENDED = play_through()
except Exception:
    crash("the playthrough loop itself")
if last := PER.get(STATE["mission"]):
    last["ended"] = here()
    last["done"] = ENDED == "CHAMPION"
    last["done"] = last["done"] or ENDED.startswith("built so far")
shot("END_" + ENDED.replace(" ", "_"))

# ---------------------------------------------------------------- after the title: every post-title event PLAYED (11-23, Jordan: "a post league content playthrough")
