for what, words, how in THINGS:
    def names(m):
        t = guide._plain(" ".join(str(m.get(k) or "") for k in ("title", "text", "description", "desc")))
        return any(_re.search(r"\b" + _re.escape(w) + r"\b", t) for w in words)
    mains = [m["id"] for m in _all if str(m.get("type")).upper() == "MAIN" and names(m)]
    sides = [m["id"] for m in _all if str(m.get("type")).upper() != "MAIN" and names(m)]
